package com.codepilot1c.core.tools.diagnostics;
import java.util.*;
import java.util.concurrent.CompletableFuture;
import com.codepilot1c.core.tools.*;
import com.codepilot1c.core.edt.development.*;
@ToolMeta(name="edt_bug_report",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtBugReportTool extends AbstractTool {
 public String getDescription(){return "Report any Bridge bug or improvement proposal to fixed Nspection/edt-agent-bridge GitHub Issues. Workflow: status; auth_start(method=browser|token|choose,stable idempotency_key) starts browser sign-in or opens the selected login UI; without Git Credential Manager, auth_start and review_request open the fixed manual issue form (browser_report_opened, report_submitted=false); prepare_async(component,report_type=bug|proposal,title+description optional, stable key); follow request_status next_call; review_request(report_id,expected_payload_sha256,key) opens exact preview and user Send button publishes it. Credentials are entered only in GitHub browser or protected EDT token field, saved once; never pass passwords/tokens through MCP/chat. verify_account is async /user verification, not issue-write proof; status is cached with last_verified_at. Custom prose always needs exact human approval, even under auto_sanitized. Journal client_id+operation_id reads existing TestClient evidence without RPC/replay; manual prose is agent supplied, never verified evidence. Legacy status/prepare/submit/reconcile remain. Prefer *_async for potentially slow work. Durable request keys prevent duplicate UI/work after MCP loss/restart; submitted/sending/delivery_unknown reports never repost. reconcile only reads acknowledgements. No automatic code/log/screenshot attachments.";}
 public String getParameterSchema(){return """
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["status","prepare","submit","reconcile","auth_start","verify_account","prepare_async","review_request","submit_async","request_status"]},"method":{"enum":["browser","token","choose"]},"idempotency_key":{"type":"string","pattern":"^[A-Za-z0-9_.:-]{1,128}$"},"request_id":{"type":"string","pattern":"^[a-f0-9]{64}$"},"component":{"enum":["testclient","native","editor","mcp"]},"report_type":{"enum":["bug","proposal"]},"title":{"type":"string","minLength":1,"maxLength":160},"description":{"type":"string","minLength":1,"maxLength":8000},"diagnostics":{"type":"object","description":"Only known codes/counters retained; never pass credentials."},"client_id":{"type":"string","pattern":"^[a-f0-9]{32}$"},"operation_id":{"type":"string","pattern":"^[a-f0-9]{64}$"},"report_id":{"type":"string","pattern":"^[a-f0-9]{64}$"},"expected_payload_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """;}
 @SuppressWarnings("unchecked") private static Map<String,Object> prepare(BugReportService service,Map<String,Object> args)throws Exception{
  boolean verified=args.containsKey("client_id")||args.containsKey("operation_id");String component=RuntimeExecutionPlan.required(args,"component");Map<String,Object> diagnostics;
  if(verified){if(!component.equals("testclient")||args.containsKey("diagnostics"))throw new IllegalArgumentException("Journal reports require testclient and both journal ids");diagnostics=new DirectTestClientService().result(RuntimeExecutionPlan.required(args,"client_id"),RuntimeExecutionPlan.required(args,"operation_id"));}
  else diagnostics=args.get("diagnostics") instanceof Map<?,?> map?(Map<String,Object>)map:Map.of();
  boolean described=args.containsKey("title")||args.containsKey("description");if(args.containsKey("report_type")&&!described)throw new IllegalArgumentException("Report type requires explicit title and description");var row=described?service.prepareDescription(component,diagnostics,verified,RuntimeExecutionPlan.required(args,"title"),RuntimeExecutionPlan.required(args,"description"),Objects.toString(args.getOrDefault("report_type","bug"))):service.prepare(component,diagnostics,verified);
  var result=new LinkedHashMap<>(row);if("prepared".equals(row.get("state")))result.put("next_call",BugReportRequests.call(Map.of("action","review_request","report_id",row.get("report_id"),"expected_payload_sha256",row.get("payload_sha256"),"idempotency_key","review-"+DirectClientJournal.hash(Objects.toString(args.get("idempotency_key"),"legacy")+"\n"+row.get("report_id")+"\n"+row.get("payload_sha256")))));return result;
 }
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{
  var args=new LinkedHashMap<String,Object>(p.getRaw());String action=RuntimeExecutionPlan.required(args,"action");var service=BugReportService.workspace();if(action.equals("prepare")||action.equals("prepare_async"))args.putIfAbsent("component","mcp");
  Set<String> fields=switch(action){case "status","reconcile"->Set.of("action","report_id");case "submit"->Set.of("action","report_id","expected_payload_sha256");case "submit_async","review_request"->Set.of("action","report_id","expected_payload_sha256","idempotency_key");case "request_status"->Set.of("action","request_id");case "auth_start"->Set.of("action","method","idempotency_key");case "verify_account"->Set.of("action","idempotency_key");case "prepare","prepare_async"->Set.of("action","component","diagnostics","client_id","operation_id","report_type","title","description","idempotency_key");default->throw new IllegalArgumentException("Unsupported report action");};if(!fields.containsAll(args.keySet()))throw new IllegalArgumentException("Fields do not apply to report action");
  Object result;
  if(Set.of("auth_start","verify_account","prepare_async","review_request","submit_async").contains(action)){
   String key=RuntimeExecutionPlan.required(args,"idempotency_key");var payload=new TreeMap<>(args);payload.remove("idempotency_key");
   if(args.get("title") instanceof String title){args.put("title",BugReportEnvelope.publicTextForDraft(title,true));payload.put("title",args.get("title"));}if(args.get("description") instanceof String description){args.put("description",BugReportEnvelope.publicTextForDraft(description,false));payload.put("description",args.get("description"));}
   if(args.get("diagnostics") instanceof Map<?,?> raw){var clean=BugReportEnvelope.collect(RuntimeExecutionPlan.required(args,"component"),"unknown",(Map<String,Object>)raw,false);args.put("diagnostics",clean);payload.put("diagnostics",clean);}
   String kind=action.equals("auth_start")?"auth":action.equals("review_request")?"review":action;
   var requests=BugReportRequests.workspace();
   if(action.equals("auth_start")||action.equals("review_request"))result=requests.startUi(kind,key,payload,()->action.equals("auth_start")?BugReportRequests.interact("auth",Objects.toString(args.getOrDefault("method","choose")),"",""):BugReportRequests.interact("review","",RuntimeExecutionPlan.required(args,"report_id"),RuntimeExecutionPlan.required(args,"expected_payload_sha256")));
   else result=requests.start(kind,key,payload,()->switch(action){case "verify_account"->service.verifyAccount();case "prepare_async"->prepare(service,args);default->service.submit(RuntimeExecutionPlan.required(args,"report_id"),RuntimeExecutionPlan.required(args,"expected_payload_sha256"));});
  }else if(action.equals("request_status"))result=BugReportRequests.workspace().status(RuntimeExecutionPlan.required(args,"request_id"));
  else if(action.equals("prepare"))return CompletableFuture.supplyAsync(()->{try{return ToolResult.success(AgentResponses.JSON.toJson(prepare(service,args)));}catch(Exception error){return unavailable(error);}});
  else if(action.equals("submit")||action.equals("reconcile"))return CompletableFuture.supplyAsync(()->{try{return ToolResult.success(AgentResponses.JSON.toJson(action.equals("submit")?service.submit(RuntimeExecutionPlan.required(args,"report_id"),RuntimeExecutionPlan.required(args,"expected_payload_sha256")):service.reconcile(RuntimeExecutionPlan.required(args,"report_id"))));}catch(Exception error){return unavailable(error);}});
  else result=args.containsKey("report_id")?service.result(RuntimeExecutionPlan.required(args,"report_id")):service.status();
  return CompletableFuture.completedFuture(ToolResult.success(AgentResponses.JSON.toJson(result)));
 }catch(Exception failure){return CompletableFuture.completedFuture(unavailable(failure));}}
 private static ToolResult unavailable(Exception failure){return ToolResult.failure("BUG_REPORT_UNAVAILABLE: "+failure.getClass().getSimpleName()+". Use status/request_status and the original request/report ids; no automatic replay.");}
}
